const raw = $input.item.json.body ?? $input.item.json;

// --- AUDIO: mídia vinda do CRM ---
const mediaType = raw.mediaType ?? null;
const mediaUrl = raw.mediaUrl ?? null;

const origemMap = {
  whatsapp: 'whatsapp',
  lovable: 'lovable',
  instagram: 'instagram_futuro',
  loja: 'atendimento_loja'
};
const origem_lead = origemMap[raw.canal] ?? 'whatsapp';

const history = (raw.contexto ?? [])
  .filter(m => m.tipo !== 'interno')
  .slice(-10)
  .map(m => ({
    role: m.tipo === 'cliente' ? 'cliente' : m.tipo === 'bia' ? 'bia' : 'atendente',
    text: m.texto,
    at: m.criadoEm
  }));

const is_first_contact = history.filter(m => m.role === 'cliente').length <= 1;

let pre_qualified = { uso_principal: null, orcamento: null, estado: null, prioridade: null };
if (origem_lead === 'lovable') {
  try {
    const pq = JSON.parse(raw.mensagemCliente);
    pre_qualified = {
      uso_principal: pq.uso_principal ?? null,
      orcamento: pq.orcamento ?? null,
      estado: pq.estado ?? null,
      prioridade: pq.prioridade ?? null
    };
  } catch (_) {}
}

return {
  json: {
    lead_id: raw.leadId,
    lead_nome: raw.leadNome ?? null,
    origem_lead,
    current_message: mediaType === 'audio' ? '' : (raw.mensagemCliente ?? ''),
    mediaType,
    mediaUrl,
    resumo: raw.resumo ?? null,
    is_first_contact,
    history,
    pre_qualified
  }
};

// ============================================================
// FIX A — preparar_prompt (injeta data/hora/dia da semana)
// ============================================================
// SUBSTITUIR o código atual do nó `preparar_prompt` por este.

const item = $input.item.json;

// ===== Data/hora atual em timezone Brasil =====
const agora = new Date();
// Ajusta pra timezone São Paulo (UTC-3)
const tzOffset = -3;
const agoraBR = new Date(agora.getTime() + (tzOffset * 60 - agora.getTimezoneOffset()) * 60000);

const diasSemana = ['domingo','segunda','terca','quarta','quinta','sexta','sabado'];
const diaSemana = diasSemana[agoraBR.getDay()];
const dataFmt = agoraBR.toISOString().slice(0,10); // 2026-05-24
const horaFmt = agoraBR.toTimeString().slice(0,5); // 09:19

// ===== Status da loja agora =====
let statusLoja;
if (diaSemana === 'domingo') {
  statusLoja = 'FECHADA (domingo)';
} else if (diaSemana === 'sabado') {
  const h = agoraBR.getHours();
  statusLoja = (h >= 9 && h < 17) ? 'ABERTA (sábado 9h-17h)' : 'FECHADA (fora do horário de sábado)';
} else {
  const h = agoraBR.getHours();
  statusLoja = (h >= 9 && h < 18) ? 'ABERTA (seg-sex 9h-18h)' : 'FECHADA (fora do horário comercial)';
}

// ===== Histórico (últimas 10, filtrando "vícios linguísticos") =====
const VICIOS = ['me chama no privado', 'chama no privado', 'me chama no particular'];

let hist = '(sem histórico)';
if (Array.isArray(item.history) && item.history.length) {
  const ultimas = item.history
    .slice(-10)
    .filter(m => {
      if (m.role !== 'bia') return true;
      // descarta msgs da Bia com vícios linguísticos antigos
      const t = (m.text || '').toLowerCase();
      return !VICIOS.some(v => t.includes(v));
    });

  hist = ultimas.map(m => `[${m.role}]: ${m.text}`).join('\n');
}

// ===== Pré-qualificação (lovable) =====
let pqLines = '(não aplicável)';
if (item.pre_qualified && Object.keys(item.pre_qualified).length) {
  pqLines = Object.entries(item.pre_qualified)
    .map(([k,v]) => `- ${k}: ${v}`)
    .join('\n');
}

// ===== Montagem do prompt =====
const prompt = [
  `DATA ATUAL: ${dataFmt} (${diaSemana})`,
  `HORÁRIO ATUAL: ${horaFmt}`,
  `STATUS DA LOJA AGORA: ${statusLoja}`,
  '',
  `ORIGEM: ${item.origem_lead ?? 'whatsapp'}`,
  `LEAD: ${item.lead_nome ?? 'não identificado'}`,
  `PRIMEIRO CONTATO: ${item.is_first_contact ? 'sim' : 'não'}`,
  `RESUMO ANTERIOR: ${item.resumo ?? 'nenhum'}`,
  '',
  'HISTÓRICO (últimas 10 msgs, filtrado):',
  hist,
  '',
  'PRÉ-QUALIFICAÇÃO:',
  pqLines,
  '',
  'MENSAGEM ATUAL DO CLIENTE:',
  item.current_message
].join('\n');

return {
  json: {
    ...item,
    prompt,
    data_atual: dataFmt,
    dia_semana: diaSemana,
    hora_atual: horaFmt,
    status_loja: statusLoja
  }
};

const raw = $input.item.json;
const classificacao = raw.output ?? raw;
const normalizado = $('normalizar_entrada').item.json;

// status da loja (vem do preparar_prompt)
const promptCtx = $('preparar_prompt').item.json || {};
const status_loja = promptCtx.status_loja || '';
const lojaFechada = String(status_loja).includes('FECHADA');

const blacklist = [
  'em estoque', 'temos disponível', 'tenho aqui',
  'saúde da bateria', 'bateria está', 'capacidade da bateria',
  'promoção especial', 'condição especial',
  'reservado', 'posso reservar', 'vou reservar',
  'garanto', 'confirmo disponibilidade',
  // reforcos contra promessa de estoque/preco
  'última unidade', 'entrega hoje', 'frete grátis',
  'consigo por', 'faço por', 'melhor preço da cidade'
];

let response_text = classificacao.output ?? classificacao.response_text ?? 'Nosso time de vendas pode te ajudar! Posso conectar você agora?';
let humano = classificacao.humano ?? false;
let handoff_reason = null;

const lower = (response_text || '').toLowerCase();
if (blacklist.some(kw => lower.includes(kw))) {
  response_text = 'Vou te passar pra um atendente que confirma isso certinho pra você, só um instante 🙏';
  humano = true;
  handoff_reason = 'violation_blacklist';
}

// MODO SILENCIOSO real: nao envia mensagem vazia
const estado = classificacao.estado_atendimento ?? 'qualificando';
const should_send = classificacao.should_send ?? true;
const isSilencioso = (estado === 'silencioso') || (should_send === false) || !String(response_text || '').trim();

// FORA DO HORARIO: nao faz handoff (nao tem atendente). Bia segue atendendo.
if (lojaFechada) {
  humano = false;
  handoff_reason = null;
}

if (humano && !handoff_reason) handoff_reason = 'ai_decision';

return {
  json: {
    crm_payload: {
      lead_id: normalizado.lead_id,
      respostas: isSilencioso ? [] : [{ texto: response_text, mediaUrl: null }],
      metadata: {
        intencao: classificacao.intencao ?? 'outro',
        complexidade: classificacao.complexidade ?? 'simples',
        lead_score: classificacao.lead_score ?? 0,
        urgencia: classificacao.urgencia ?? 'baixa',
        estado_atendimento: estado,
        origem_lead: normalizado.origem_lead,
        resumo: classificacao.resumo ?? null,
        humano: humano,
        handoff_reason: handoff_reason,
        status_loja: status_loja
      }
    }
  }
};

const item = $input.item;
const bin = item.binary?.data;
if (bin) {
  bin.fileName = 'audio.ogg';
  bin.fileExtension = 'ogg';
  bin.mimeType = 'audio/ogg';
}
return item;
